/// OWNERSHIP_SQL from utils/deckOwnership.js.
pub(crate) const OWNERSHIP_SQL: &str = r#"
  WITH need AS (
    SELECT
      dc.deck_id,
      LOWER(TRIM(COALESCE(cc.name, ''))) AS card_key,
      SUM(dc.quantity) AS need_qty,
      MAX(((LOWER(COALESCE(cc.supertype, '')) = 'land' OR INSTR(LOWER(COALESCE(cc.subtypes, '')), '"land"') > 0) AND (LOWER(TRIM(COALESCE(cc.name, ''))) IN ('plains', 'island', 'swamp', 'mountain', 'forest', 'wastes') OR INSTR(LOWER(COALESCE(cc.subtypes, '')), '"basic"') > 0))) AS is_basic
    FROM deck_cards dc
    JOIN decks d ON d.id = dc.deck_id
    JOIN card_cache cc ON cc.id = dc.card_id
    WHERE d.user_id = ? AND dc.quantity > 0
    GROUP BY dc.deck_id, LOWER(TRIM(COALESCE(cc.name, '')))
  ),
  owned AS (
    SELECT LOWER(TRIM(COALESCE(occ.name, ''))) AS card_key, SUM(o.quantity) AS owned_qty
    -- Only keys some deck needs; card_cache first so collection is probed by
    -- idx_collection_card_user instead of aggregated whole.
    FROM card_cache occ
    CROSS JOIN collection o
    WHERE o.card_id = occ.id AND o.user_id = ? AND o.quantity > 0
      AND LOWER(TRIM(COALESCE(occ.name, ''))) IN (SELECT card_key FROM need)
    GROUP BY LOWER(TRIM(COALESCE(occ.name, '')))
  )
  SELECT
    need.deck_id,
    SUM(CASE WHEN need.is_basic = 0 AND COALESCE(owned.owned_qty, 0) < need.need_qty
             THEN 1 ELSE 0 END) AS missing_card_types,
    SUM(CASE WHEN need.is_basic = 0 AND COALESCE(owned.owned_qty, 0) < need.need_qty
             THEN need.need_qty - COALESCE(owned.owned_qty, 0) ELSE 0 END) AS missing_copies
  FROM need
  LEFT JOIN owned ON owned.card_key = need.card_key
  GROUP BY need.deck_id
"#;
